191	        this.possibleDuplicate = possibleDuplicate;
192	    }
193	
194	    public Integer getPossibleDuplicateOf() {
195	        return this.possibleDuplicateOf;
196	    }
197	
198	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
199	        this.possibleDuplicateOf = possibleDuplicateOf;
200	    }
201	
202	    protected Set<Pet> getPetsInternal() {
203	        if (this.pets == null) {
204	            this.pets = new HashSet<>();
205	        }
206	        return this.pets;
207	    }
208	
209	    protected void setPetsInternal(Set<Pet> pets) {
210	        this.pets = pets;
211	    }
212	
213	    public List<Pet> getPets() {
214	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
215	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
216	        return Collections.unmodifiableList(sortedPets);
217	    }
218	
219	    public void setPets(List<Pet> pets) {
220	        this.pets = new HashSet<>(pets);
221	    }
222	
223	    public void addPet(Pet pet) {
224	        getPetsInternal().add(pet);
225	        pet.setOwner(this);
226	    }
227	
228	    /**
229	     * Return the Pet with the given name, or null if none found for this Owner.
230	     *
231	     * @param name to test
232	     * @return true if pet name is already in use
233	     */
234	    public Pet getPet(String name) {
235	        return getPet(name, false);
236	    }
237	
238	    /**
239	     * Return the Pet with the given name, or null if none found for this Owner.
240	     *
241	     * @param name to test
242	     * @return true if pet name is already in use
243	     */
244	    public Pet getPet(String name, boolean ignoreNew) {
245	        name = name.toLowerCase();
246	        for (Pet pet : getPetsInternal()) {
247	            if (!ignoreNew || !pet.isNew()) {
248	                String compName = pet.getName();
249	                compName = compName.toLowerCase();
250	                if (compName.equals(name)) {
251	                    return pet;
252	                }
253	            }
254	        }
255	        return null;
256	    }
257	
258	    public Pet getPet(Integer petId) {
259	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
260	    }
261	
262	    @Override
263	    public String toString() {
264	        return new ToStringCreator(this)
265	
266	            .append("id", this.getId())
267	            .append("new", this.isNew())
268	            .append("lastName", this.getLastName())
269	            .append("firstName", this.getFirstName())
270	            .append("address", this.address)
271	            .append("city", this.city)
272	            .append("telephone", this.telephone)
273	            .append("email", this.email)
274	            .toString();
275	    }
276	}
