1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.AgeBand;
8	import org.springframework.samples.petclinic.model.ContactPreference;
9	import org.springframework.samples.petclinic.model.Locality;
10	import org.springframework.samples.petclinic.model.MembershipLevel;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.rest.function.owner.OwnerIdentities;
13	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
14	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
15	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
16	import org.springframework.samples.petclinic.util.Luhn;
17	
18	import java.util.Collection;
19	import java.util.List;
20	
21	/**
22	 * Maps Owner & OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public interface OwnerMapper {
26	
27	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
28	    @Mapping(target = "initials", expression = "java(initials(owner))")
29	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
30	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
31	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
32	    @Mapping(target = "locality", expression = "java(locality(owner))")
33	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
34	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
35	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    /** The owner's age band derived from birthDate against registrationDate - see {@link AgeBand};
39	     * null when either date is absent. */
40	    default String ageBand(Owner owner) {
41	        if (owner == null) {
42	            return null;
43	        }
44	        AgeBand ageBand = AgeBand.forOwner(owner);
45	        return ageBand == null ? null : ageBand.name();
46	    }
47	
48	    /** The owner's derived duplicate-detection key - see {@link OwnerIdentities}. */
49	    default String identityKey(Owner owner) {
50	        if (owner == null) {
51	            return null;
52	        }
53	        return OwnerIdentities.of(owner);
54	    }
55	
56	    /** The owner's preferred contact channel - 'EMAIL' when an email is present, otherwise 'PHONE'. */
57	    default String contactPreference(Owner owner) {
58	        if (owner == null) {
59	            return null;
60	        }
61	        return ContactPreference.forOwner(owner).name();
62	    }
63	
64	    /** The canonical region derived from the owner's postcode - the same REGION that forms the
65	     * customer code (see {@link OwnerIdentities} and the {@code <REGION>-<HASH8>} customer code),
66	     * or 'UNKNOWN' when the postcode resolves to no known region. */
67	    default String locality(Owner owner) {
68	        if (owner == null) {
69	            return null;
70	        }
71	        return Locality.forPostcode(owner.getPostcode());
72	    }
73	
74	    /** Format the stored names as 'LastName, FirstName'. */
75	    default String displayName(Owner owner) {
76	        if (owner == null) {
77	            return null;
78	        }
79	        return owner.getLastName() + ", " + owner.getFirstName();
80	    }
81	
82	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot (e.g. 'J.S.'). */
83	    default String initials(Owner owner) {
84	        if (owner == null) {
85	            return null;
86	        }
87	        return initial(owner.getFirstName()) + initial(owner.getLastName());
88	    }
89	
90	    private static String initial(String name) {
91	        if (name == null || name.isEmpty()) {
92	            return "";
93	        }
94	        return Character.toUpperCase(name.charAt(0)) + ".";
95	    }
96	
97	    /**
98	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
99	     * last two digits of the registrationDate year (e.g. 'NSW-1A2B3C4D-M26'). Derived from the owner's
100	     * own fields; null until both the customer code and registration date are assigned.
101	     */
102	    default String membershipNumber(Owner owner) {
103	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
104	            return null;
105	        }
106	        return owner.getCustomerCode() + "-M" + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
107	    }
108	
109	    /** The Luhn check digit over the digits of the owner's customerCode; null until a code is assigned. */
110	    default Integer checkDigit(Owner owner) {
111	        if (owner == null || owner.getCustomerCode() == null) {
112	            return null;
113	        }
114	        return Luhn.checkDigit(owner.getCustomerCode());
115	    }
116	
117	    /**
118	     * The owner's numeric membership level, derived from the owner's own fields; null when there
119	     * is no owner.
120	     *
121	     * @see MembershipLevel
122	     */
123	    default Integer membershipLevel(Owner owner) {
124	        if (owner == null) {
125	            return null;
126	        }
127	        return MembershipLevel.of(owner);
128	    }
129	
130	    Owner toOwner(OwnerDto ownerDto);
131	
132	    @Mapping(target = "id", ignore = true)
133	    @Mapping(target = "pets", ignore = true)
134	    Owner toOwner(OwnerFieldsDto ownerDto);
135	
136	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
137	
138	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
139	
140	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
141	        OwnerPageDto ownerPageDto = new OwnerPageDto();
142	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
143	        ownerPageDto.setPage(ownerPage.getNumber());
144	        ownerPageDto.setSize(ownerPage.getSize());
145	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
146	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
147	        return ownerPageDto;
148	    }
149	}
